# math-booster MathWiki style icons per theorem type; other theorem types use Obsidian's default (pencil).
THEOREM_ICON = {"axiom": "lock", "definition": "book", "theorem": "magic", "proposition": "calculator", "example": "anchor"}


def callout_icon(ctype: str, theorem: bool) -> str:
    """A <use> reference into the sprite emitted by sprite_html() (layouts/partials/callout-icons.html)."""
    if theorem and ctype in THEOREM_ICON:
        name = "fa-" + THEOREM_ICON[ctype]
        return f'<svg class="svg-inline--fa" viewBox="{_FA_VB[THEOREM_ICON[ctype]]}"><use href="#cicon-{name}"/></svg>'
    name = CALLOUT_ICON.get(ctype, "pencil")
    return f'<svg class="lucide lucide-{name}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><use href="#cicon-{name}"/></svg>'


_FA_VB = {"lock": "0 0 448 512", "book": "0 0 448 512", "magic": "0 0 512 512", "calculator": "0 0 448 512", "anchor": "0 0 576 512"}


def sprite_html() -> str:
    import re
    parts = ['<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">']
    for name, svg in LUCIDE.items():
        body = re.sub(r"^<svg[^>]*>|</svg>$", "", svg)
        parts.append(f'<symbol id="cicon-{name}" viewBox="0 0 24 24">{body}</symbol>')
    for name, svg in FA.items():
        body = re.sub(r"^<svg[^>]*>|</svg>$", "", svg)
        parts.append(f'<symbol id="cicon-fa-{name}" viewBox="{_FA_VB[name]}">{body}</symbol>')
    parts.append("</svg>")
    return "\n".join(parts) + "\n"
